"""Generated by OpenAI Codex on 2026-11-03. One-time, transactional map import."""

import argparse
import hashlib
import json
import sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "back_end/app"))
from sqlalchemy import text
from database.database import engine
from services.campus_map import (
    geometries,
    normalize_links,
    parse_osm,
    persist,
    validate_graph,
)


def run(path, if_empty=False):
    if if_empty:
        with engine.connect() as db:
            if db.execute(
                text("SELECT revision FROM map_dataset WHERE singleton")
            ).scalar_one():
                print("Map already imported; database edits preserved.")
                return
    content = path.read_bytes()
    objects = parse_osm(content)
    validate_graph(
        objects, objects
    )  # Preserve missing references already in the extract.
    normalize_links(objects)
    geometry, status = geometries(objects)
    with engine.begin() as db:
        revision = db.execute(
            text("SELECT revision FROM map_dataset WHERE singleton FOR UPDATE")
        ).scalar_one()
        if revision:
            if if_empty:
                print("Map already imported; database edits preserved.")
                return
            raise SystemExit(
                "Map is already initialized. Refusing to overwrite database edits."
            )
        persist(db, objects, geometry, status)
        db.execute(
            text(
                "UPDATE map_dataset SET revision=1,source_sha256=:digest,imported_at=now() WHERE singleton"
            ),
            {"digest": hashlib.sha256(content).hexdigest()},
        )
        db.execute(
            text(
                "INSERT INTO map_changes(revision,actor_sub,actor_email,before_state,after_state) VALUES(1,'import','administrator','{}',CAST(:report AS jsonb))"
            ),
            {
                "report": json.dumps(
                    {
                        "source_sha256": hashlib.sha256(content).hexdigest(),
                        "count": len(objects),
                    }
                )
            },
        )
    print(
        json.dumps(
            {
                "objects": len(objects),
                "entrance_links": dict(
                    Counter(o["link_status"] for o in objects.values())
                ),
                "geometry": dict(Counter(status.values())),
            },
            indent=2,
        )
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--file",
        type=Path,
        default=Path(__file__).resolve().parents[1] / "data/greater_cmu_area.osm",
    )
    parser.add_argument("--if-empty", action="store_true")
    args = parser.parse_args()
    run(args.file, args.if_empty)
